#!/usr/bin/env python3
"""PS1M2a: determine whether frozen packets define a canonical column-level nearby map."""
import json,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
def load(p):return json.loads((ROOT/p).read_text())
exact=load('research/benincasa/results/G12_exact_degree15_reconstruction.json');ov=load('research/benincasa/results/G12_coefficient_overlap_representatives.json');near=load('research/benincasa/full-rank12-cut-nearby-layers-certificate.json');audit=load('research/benincasa/results/PS1M2_nearby_degree15_projection_audit.json')
kinds=collections.Counter(z['kind'] for z in exact['solution']);source_labels={z['kind'] for z in exact['solution']};near_names=('g101','g110','g111_tilde');serialized=json.dumps({'exact':exact['solution'][:3],'overlap':ov.get('columns',[])[:3]})
checks={'projection_was_missing':audit['resolution']=='--','exact_basis_is_d0_plus_overlap':source_labels=={'d0','overlap'},'nearby_packet_has_three_columns':len(near['cut_nearby_algebraic_image'])==3,'no_generator_identification':all(n not in serialized for n in near_names),'only_one_common_line_fixed':near['intersection_rank']==1 and near['combined_rank']>near['intersection_rank'],'maps_nonunique_on_complement':exact['ambient_shape'][1]>near['intersection_rank']}
